const formPessoa = document.getElementById("form-pessoa");
const inputNome = document.getElementById("nome");
const inputIdade = document.getElementById("idade");
const inputAltura = document.getElementById("altura");
const inputPeso = document.getElementById("peso");
const tabelaPessoas = document.getElementById("tabela-pessoas");
const mensagemDeErro = document.getElementById("erro");

const chavePessoas = "pessoas";

// ARMAZENAMENTO
// Funciona mesmo quando a plataforma bloqueia localStorage.

function carregarPessoas() {
  try {
      const dados = localStorage.getItem(chavePessoas);

          if (dados === null) {
                return [];
                    }

                        const lista = JSON.parse(dados);
                            return Array.isArray(lista) ? lista : [];
                              } catch (erro) {
                                  console.warn("LocalStorage indisponível:", erro);
                                      return [];
                                        }
                                        }

                                        let pessoas = carregarPessoas();
                                        let contadorCodigo = 0;

                                        function salvar() {
                                          try {
                                              localStorage.setItem(
                                                    chavePessoas,
                                                          JSON.stringify(pessoas)
                                                              );
                                                                } catch (erro) {
                                                                    console.warn(
                                                                          "Dados mantidos somente durante esta execução."
                                                                              );
                                                                                }
                                                                                }

                                                                                // IDENTIFICADOR AUTOMÁTICO

                                                                                function ajustarContador() {
                                                                                  pessoas.forEach(function(pessoa) {
                                                                                      if (pessoa.id > contadorCodigo) {
                                                                                            contadorCodigo = pessoa.id;
                                                                                                }
                                                                                                  });
                                                                                                  }

                                                                                                  function gerarCodigo() {
                                                                                                    return ++contadorCodigo;
                                                                                                    }

                                                                                                    // CÁLCULO DO IMC

                                                                                                    function calcularIMC(peso, altura) {
                                                                                                      return peso / (altura * altura);
                                                                                                      }

                                                                                                      // CLASSIFICAÇÃO DO IMC

                                                                                                      function classificarIMC(imc) {
                                                                                                        if (imc < 18.5) {
                                                                                                            return {
                                                                                                                  texto: "Abaixo do peso",
                                                                                                                        classe: "abaixo"
                                                                                                                            };
                                                                                                                              }

                                                                                                                                if (imc < 25) {
                                                                                                                                    return {
                                                                                                                                          texto: "Peso normal",
                                                                                                                                                classe: "normal"
                                                                                                                                                    };
                                                                                                                                                      }

                                                                                                                                                        if (imc < 30) {
                                                                                                                                                            return {
                                                                                                                                                                  texto: "Sobrepeso",
                                                                                                                                                                        classe: "sobrepeso"
                                                                                                                                                                            };
                                                                                                                                                                              }

                                                                                                                                                                                if (imc < 35) {
                                                                                                                                                                                    return {
                                                                                                                                                                                          texto: "Obesidade grau I",
                                                                                                                                                                                                classe: "obesidade"
                                                                                                                                                                                                    };
                                                                                                                                                                                                      }

                                                                                                                                                                                                        if (imc < 40) {
                                                                                                                                                                                                            return {
                                                                                                                                                                                                                  texto: "Obesidade grau II",
                                                                                                                                                                                                                        classe: "obesidade"
                                                                                                                                                                                                                            };
                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                return {
                                                                                                                                                                                                                                    texto: "Obesidade grau III",
                                                                                                                                                                                                                                        classe: "obesidade"
                                                                                                                                                                                                                                          };
                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                          // FORMATAÇÃO DOS NÚMEROS

                                                                                                                                                                                                                                          function formatar(valor, casas) {
                                                                                                                                                                                                                                            return valor.toLocaleString("pt-BR", {
                                                                                                                                                                                                                                                minimumFractionDigits: casas,
                                                                                                                                                                                                                                                    maximumFractionDigits: casas
                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                      // CRIAÇÃO DAS CÉLULAS

                                                                                                                                                                                                                                                      function criarCelula(conteudo) {
                                                                                                                                                                                                                                                        const td = document.createElement("td");
                                                                                                                                                                                                                                                          td.textContent = conteudo;
                                                                                                                                                                                                                                                            return td;
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                            // CRIAÇÃO DAS LINHAS DA TABELA

                                                                                                                                                                                                                                                            function criarLinha(pessoa) {
                                                                                                                                                                                                                                                              const tr = document.createElement("tr");
                                                                                                                                                                                                                                                                tr.dataset.id = pessoa.id;

                                                                                                                                                                                                                                                                  const imc = calcularIMC(
                                                                                                                                                                                                                                                                      pessoa.peso,
                                                                                                                                                                                                                                                                          pessoa.altura
                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                              const classificacao = classificarIMC(imc);

                                                                                                                                                                                                                                                                                tr.appendChild(criarCelula(pessoa.nome));
                                                                                                                                                                                                                                                                                  tr.appendChild(criarCelula(pessoa.idade));

                                                                                                                                                                                                                                                                                    tr.appendChild(
                                                                                                                                                                                                                                                                                        criarCelula(formatar(pessoa.altura, 2) + " m")
                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                            tr.appendChild(
                                                                                                                                                                                                                                                                                                criarCelula(formatar(pessoa.peso, 1) + " kg")
                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                    tr.appendChild(
                                                                                                                                                                                                                                                                                                        criarCelula(formatar(imc, 1))
                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                            // Classificação colorida

                                                                                                                                                                                                                                                                                                              const tdClassificacao = document.createElement("td");
                                                                                                                                                                                                                                                                                                                const selo = document.createElement("span");

                                                                                                                                                                                                                                                                                                                  selo.classList.add(
                                                                                                                                                                                                                                                                                                                      "selo",
                                                                                                                                                                                                                                                                                                                          classificacao.classe
                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                              selo.textContent = classificacao.texto;

                                                                                                                                                                                                                                                                                                                                tdClassificacao.appendChild(selo);
                                                                                                                                                                                                                                                                                                                                  tr.appendChild(tdClassificacao);

                                                                                                                                                                                                                                                                                                                                    // Botão apagar

                                                                                                                                                                                                                                                                                                                                      const tdAcoes = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                        const botaoApagar = document.createElement("button");

                                                                                                                                                                                                                                                                                                                                          botaoApagar.type = "button";
                                                                                                                                                                                                                                                                                                                                            botaoApagar.textContent = "Apagar";
                                                                                                                                                                                                                                                                                                                                              botaoApagar.classList.add("apagar");
                                                                                                                                                                                                                                                                                                                                                botaoApagar.dataset.acao = "apagar";

                                                                                                                                                                                                                                                                                                                                                  tdAcoes.appendChild(botaoApagar);
                                                                                                                                                                                                                                                                                                                                                    tr.appendChild(tdAcoes);

                                                                                                                                                                                                                                                                                                                                                      return tr;
                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                      // ATUALIZAÇÃO DA TABELA

                                                                                                                                                                                                                                                                                                                                                      function render() {
                                                                                                                                                                                                                                                                                                                                                        tabelaPessoas.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                          if (pessoas.length === 0) {
                                                                                                                                                                                                                                                                                                                                                              const tr = document.createElement("tr");
                                                                                                                                                                                                                                                                                                                                                                  const td = document.createElement("td");

                                                                                                                                                                                                                                                                                                                                                                      td.colSpan = 7;
                                                                                                                                                                                                                                                                                                                                                                          td.classList.add("vazio");
                                                                                                                                                                                                                                                                                                                                                                              td.textContent = "Nenhuma pessoa cadastrada ainda";

                                                                                                                                                                                                                                                                                                                                                                                  tr.appendChild(td);
                                                                                                                                                                                                                                                                                                                                                                                      tabelaPessoas.appendChild(tr);
                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                              pessoas.forEach(function(pessoa) {
                                                                                                                                                                                                                                                                                                                                                                                                  tabelaPessoas.appendChild(criarLinha(pessoa));
                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                    // LEITURA DOS CAMPOS

                                                                                                                                                                                                                                                                                                                                                                                                    function converterNumero(valor) {
                                                                                                                                                                                                                                                                                                                                                                                                      return Number(String(valor).replace(",", "."));
                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                      function lerFormulario() {
                                                                                                                                                                                                                                                                                                                                                                                                        return {
                                                                                                                                                                                                                                                                                                                                                                                                            nome: inputNome.value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                idade: converterNumero(inputIdade.value),
                                                                                                                                                                                                                                                                                                                                                                                                                    altura: converterNumero(inputAltura.value),
                                                                                                                                                                                                                                                                                                                                                                                                                        peso: converterNumero(inputPeso.value)
                                                                                                                                                                                                                                                                                                                                                                                                                          };
                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                          // VALIDAÇÃO DOS DADOS

                                                                                                                                                                                                                                                                                                                                                                                                                          function validarDados(dados) {
                                                                                                                                                                                                                                                                                                                                                                                                                            if (dados.nome.length < 2) {
                                                                                                                                                                                                                                                                                                                                                                                                                                return "Informe o nome com no mínimo duas letras.";
                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                    if (
                                                                                                                                                                                                                                                                                                                                                                                                                                        !Number.isInteger(dados.idade) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                            dados.idade < 1 ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                dados.idade > 120
                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                      return "A idade deve ser um número inteiro entre 1 e 120.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                              !Number.isFinite(dados.altura) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  dados.altura < 0.5 ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      dados.altura > 2.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return "A altura deve estar entre 0,5 e 2,5 metros.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    !Number.isFinite(dados.peso) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dados.peso < 2 ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dados.peso > 500
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return "O peso deve estar entre 2 e 500 kg.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // MENSAGENS DE ERRO

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function mostrarErro(texto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mensagemDeErro.textContent = texto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          mensagemDeErro.hidden = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function limparErro() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mensagemDeErro.textContent = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              mensagemDeErro.hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // CADASTRO DE PACIENTES

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function adicionarPessoa(dados) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pessoas.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    id: gerarCodigo(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        nome: dados.nome,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            idade: dados.idade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                altura: dados.altura,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    peso: dados.peso
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // EVENTO DO FORMULÁRIO

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      formPessoa.addEventListener("submit", function(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        e.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const dados = lerFormulario();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const erro = validarDados(dados);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (erro !== "") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  mostrarErro(erro);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          limparErro();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            adicionarPessoa(dados);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              salvar();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                formPessoa.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  inputNome.focus();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // BOTÃO CANCELAR

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    formPessoa.addEventListener("reset", function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      limparErro();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // BOTÃO APAGAR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Utiliza delegação de eventos.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tabelaPessoas.addEventListener("click", function(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const botao = e.target.closest(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "button[data-acao='apagar']"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!botao) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const linha = botao.closest("tr");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const id = Number(linha.dataset.id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pessoas = pessoas.filter(function(pessoa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return pessoa.id !== id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // INICIALIZAÇÃO

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ajustarContador();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      render();